pub const fn mordekaiser_q1(ctx: &Ctx) -> f32 {
    5f32 * (5f32 + ctx.q_level)
}

pub const fn mordekaiser_q2(ctx: &Ctx) -> f32 {
    ((((80.0) + (35.0 * (ctx.q_level - 1.0))) + ((1.2) * ctx.bonus_ad))
        + ((0.7) * ctx.ability_power))
        + (match ctx.level as u8 {
            ..10 => 0.0,
            10 => 5.0,
            11 => 10.0,
            12 => 15.0,
            13 => 20.0,
            14 => 25.0,
            15 => 30.0,
            16 => 35.0,
            17 => 40.0,
            18 => 45.0,
            19 => 50.0,
            20.. => 55.0,
        })
}

pub const fn mordekaiser_e1(ctx: &Ctx) -> f32 {
    15f32 * (3f32 + 0.02666666666666667 * ctx.ability_power + ctx.e_level)
}

