pub const fn zoe_q2(ctx: &Ctx) -> f32 {
    4f32 * (13f32 + 0.15 * ctx.ability_power + 8f32 * (-1f32 + ctx.level))
}

pub const fn zoe_w1(ctx: &Ctx) -> f32 {
    5f32 * (3f32 + 0.02 * ctx.ability_power + 2f32 * (-1f32 + ctx.w_level))
}

pub const fn zoe_w2(ctx: &Ctx) -> f32 {
    15f32 * (3f32 + 0.02 * ctx.ability_power + 2f32 * (-1f32 + ctx.w_level))
}

pub const fn zoe_e1(ctx: &Ctx) -> f32 {
    10f32 * (7f32 + 0.045 * ctx.ability_power + 4f32 * (-1f32 + ctx.e_level))
}

pub const fn zoe_e2(ctx: &Ctx) -> f32 {
    10f32 * (7f32 + 0.045 * ctx.ability_power + 4f32 * (-1f32 + ctx.e_level))
}

pub const fn zoe_e3(ctx: &Ctx) -> f32 {
    20f32 * (7f32 + 0.045 * ctx.ability_power + 4f32 * (-1f32 + ctx.e_level))
}

